-- Fuente: https://saa.ues.edu.sv/aspirantes/planes
-- Consulta pública onRequestApiCar, facultad 914 (Facultad Multidisciplinaria Oriental).
-- Consulta: 2026-11-19. Se conserva cada versión publicada, incluidas ofertas 2027.
BEGIN;
CREATE TEMP TABLE planes_portal_fmo(carrera text,nombre text,url text) ON COMMIT DROP;
SELECT c.id_carrera,p.nombre,p.url,true FROM planes_portal_fmo p
JOIN public.carreras c ON c.nombre=p.carrera
ON CONFLICT(id_carrera,nombre) DO UPDATE
SET documento_url=coalesce(public.planes_estudio.documento_url,excluded.documento_url);
COMMIT;
